pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }

    // Fuzz parameters: _baseToken and _nft addresses and numeric parameters that initialize accepts.
    function testFuzz_property(address _baseToken, address _nft, uint128 _virtualBaseTokenReserves, uint128 _virtualNftReserves, uint56 _changeFee, uint16 _feeRate, bytes32 _merkleRoot, bool _useStolenNftOracle, bool _payRoyalties) public {
        // Keep feeRate within allowed bounds (wide): 0..65535 but contract requires <=5000.
        // We only need to avoid excluding bug-triggering inputs, so bound feeRate to [0, 5000] to ensure initialize won't revert due to FeeRateTooHigh.
        _feeRate = uint16(bound(uint256(_feeRate), 0, 5000));

        // No other constraints; call initialize and observe nft() afterwards.
        // Use try/catch to detect if initialize reverts; if it reverts then property vacuously holds for that input.
        bool ok;
        try c.initialize(_baseToken, _nft, _virtualBaseTokenReserves, _virtualNftReserves, _changeFee, _feeRate, _merkleRoot, _useStolenNftOracle, _payRoyalties) {
            ok = true;
        } catch {
            ok = false;
        }

        if (ok) {
            // After a successful initialize, the reference implementation always sets nft() == _nft.
            // The mutant may set nft() to Factory(factory).ownerOf(uint160(address(this))) instead, causing inequality for some inputs.
            assertTrue(c.nft() == _nft);
        } else {
            // If initialize reverted, we still must succeed the test on the reference contract for all inputs.
            // Do nothing further; a revert means the property (for successful inits) isn't violated here.
            assertTrue(true);
        }
    }
}

