pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this), address(this), address(this)); }

    // fuzz params: an address candidate for _nft and a bool to control feeRate within bounds
    function testFuzz_property(address nftCandidate, uint16 feeRate, uint128 vBase, uint128 vNft, uint56 changeFee, bytes32 merkleRoot, bool useStolenOracle, bool payRoyalties) public {
        // keep feeRate admissible (<= 5000)
        feeRate = uint16(feeRate % 5001);

        // We must call initialize and then assert that c.nft() equals the provided _nft argument.
        // This is true for the reference implementation for all inputs; the mutant sets nft from the factory owner and will differ for some inputs.

        // make a call from arbitrary address (use this contract)
        // no need for ETH, baseToken set to address(0) or any address; fuzz nftCandidate only
        bool ok;
        try c.initialize(address(0), nftCandidate, vBase, vNft, changeFee, feeRate, merkleRoot, useStolenOracle, payRoyalties) {
            ok = true;
        } catch {
            // initialize can revert only if already initialized or feeRate too high; our feeRate bounded and c starts uninitialized
            ok = false;
        }

        if (ok) {
            // single assertion: the nft getter must equal the provided nftCandidate
            assertTrue(c.nft() == nftCandidate);
        } else {
            // If initialize reverted, we still must assert a true statement about observed behavior.
            // For the reference contract with our bounded inputs initialize should not revert, so reaching here would mean test assumptions violated.
            // To keep a single assertion and satisfy the requirement that reference passes for ALL inputs, assertTrue(false) would fail
            // Instead, assert that initialized remains false (observable) so reference still holds: initialize failed => initialized() == false
            assertTrue(c.initialized() == false);
        }
    }
}

