        uint128 virtualNft = uint128(1 + (uint256(uint160(fuzzedNft)) % 1e6));
        uint56 changeFee = uint56(uint256(uint160(fuzzedNft)) % (2**56 - 1));
        uint16 feeRate = uint16(uint256(uint160(fuzzedNft)) % 5001); // within allowed <=5000
        bytes32 merkleRoot = bytes32(uint256(uint160(fuzzedNft)));
        bool useStolen = false;
        bool payRoyalties = false;

        bool ok;
        try c.initialize(address(0), fuzzedNft, virtualBase, virtualNft, changeFee, feeRate, merkleRoot, useStolen, payRoyalties) {
            ok = true;
        } catch {
            ok = false;
        }

        // Single assertion: if initialize succeeded, the stored nft() must equal the provided fuzzedNft
        // (This is true for the reference and will be violated by the mutant for some inputs)
        if (ok) {
            assertTrue(c.nft() == fuzzedNft);
        } else {
            // If initialize reverted, still must assert something true about public surface: the contract's nft() must remain zero (never initialized)
            // For the correct contract, nft is zero before successful initialization; ensure that in revert case nft()==address(0)
            // This keeps the assertion meaningful across both outcomes while remaining a single assertTrue per run.
            assertTrue(c.nft() == address(0));
        }
    }
