            ok = true;
        } catch {
            ok = false;
        }

        // exactly one assertion: after initialize completes successfully, feeRate() must equal the provided _feeRate.
        // This is a universal property for the reference; the mutant allows a reentrant observer to see initialized==true
        // before feeRate assigned and may cause a mismatch observable after return in some attack patterns.
        if (ok) {
            assertTrue(c.feeRate() == _feeRate);
        } else {
            // if initialize reverted, still assert that it reverted only when feeRate was out of bounds (we bounded it),
